-- League model 5 (#2002, plans/league-model-redesign.md §1): each sport league's timeless phase and
-- slot definitions, and how each provider's games match a slot, set here for every league on or
-- off, so switching one on needs no new rows. Seasons and their slots come in slice 6.

-- CreateEnum
CREATE TYPE "PrismaLeaguePhase" AS ENUM ('PRESEASON', 'REGULAR', 'POSTSEASON');

-- CreateEnum
CREATE TYPE "PrismaSlotKind" AS ENUM ('WEEK', 'PLAY_IN', 'ROUND_OF_64', 'ROUND_OF_32', 'ROUND_OF_16', 'QUARTERFINAL', 'SEMIFINAL', 'THIRD_PLACE', 'FINAL', 'TOURNAMENT');

-- CreateEnum
CREATE TYPE "PrismaSeriesFormat" AS ENUM ('SINGLE_GAME', 'BEST_OF', 'AGGREGATE');

-- CreateEnum
CREATE TYPE "PrismaSlotPairing" AS ENUM ('FIXED', 'RESEEDED');

-- CreateEnum
CREATE TYPE "PrismaSlotProviderMatchType" AS ENUM ('PROVIDER_CODE', 'NAME_PATTERN', 'DATE_WINDOW', 'CALENDAR_WEEK');

-- CreateTable
CREATE TABLE "sport_league_phases" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "sport_league_id" UUID NOT NULL,
    "phase" "PrismaLeaguePhase" NOT NULL,
    "is_synced" BOOLEAN NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL,

    CONSTRAINT "sport_league_phases_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "sport_league_phase_slots" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "sport_league_id" UUID NOT NULL,
    "sport_league_phase_id" UUID NOT NULL,
    "key" VARCHAR(64) NOT NULL,
    "slot_kind" "PrismaSlotKind" NOT NULL,
    "week_number" INTEGER,
    "name" VARCHAR(100),
    "awards_trophy" BOOLEAN NOT NULL,
    "squares_eligible" BOOLEAN NOT NULL,
    "series_format" "PrismaSeriesFormat" NOT NULL,
    "series_games" INTEGER NOT NULL,
    "pairing" "PrismaSlotPairing" NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL,

    CONSTRAINT "sport_league_phase_slots_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "sport_league_phase_slot_provider_mappings" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "sport_league_id" UUID NOT NULL,
    "sport_league_phase_slot_id" UUID NOT NULL,
    "sport_league_provider_mapping_id" UUID NOT NULL,
    "match_type" "PrismaSlotProviderMatchType" NOT NULL,
    "provider_value" VARCHAR(200),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL,

    CONSTRAINT "sport_league_phase_slot_provider_mappings_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "sport_league_phases_sport_league_id_phase_key" ON "sport_league_phases"("sport_league_id", "phase");

-- CreateIndex
CREATE UNIQUE INDEX "sport_league_phases_sport_league_id_id_key" ON "sport_league_phases"("sport_league_id", "id");

-- CreateIndex
CREATE INDEX "sport_league_phase_slots_sport_league_id_sport_league_phase_idx" ON "sport_league_phase_slots"("sport_league_id", "sport_league_phase_id");

-- CreateIndex
CREATE UNIQUE INDEX "sport_league_phase_slots_sport_league_id_key_key" ON "sport_league_phase_slots"("sport_league_id", "key");

-- CreateIndex
CREATE UNIQUE INDEX "sport_league_phase_slots_sport_league_id_id_key" ON "sport_league_phase_slots"("sport_league_id", "id");

-- CreateIndex
CREATE INDEX "sport_league_phase_slot_provider_mappings_slot_idx" ON "sport_league_phase_slot_provider_mappings"("sport_league_id", "sport_league_phase_slot_id");

-- CreateIndex
CREATE INDEX "sport_league_phase_slot_provider_mappings_provider_mapping_idx" ON "sport_league_phase_slot_provider_mappings"("sport_league_id", "sport_league_provider_mapping_id");

-- CreateIndex
CREATE UNIQUE INDEX "sport_league_phase_slot_provider_mappings_value_key" ON "sport_league_phase_slot_provider_mappings"("sport_league_provider_mapping_id", "match_type", "provider_value");

-- AddForeignKey
ALTER TABLE "sport_league_phases" ADD CONSTRAINT "sport_league_phases_sport_league_id_fkey" FOREIGN KEY ("sport_league_id") REFERENCES "sport_leagues"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "sport_league_phase_slots" ADD CONSTRAINT "sport_league_phase_slots_sport_league_id_fkey" FOREIGN KEY ("sport_league_id") REFERENCES "sport_leagues"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "sport_league_phase_slots" ADD CONSTRAINT "sport_league_phase_slots_sport_league_id_sport_league_phas_fkey" FOREIGN KEY ("sport_league_id", "sport_league_phase_id") REFERENCES "sport_league_phases"("sport_league_id", "id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "sport_league_phase_slot_provider_mappings" ADD CONSTRAINT "sport_league_phase_slot_provider_mappings_slot_fkey" FOREIGN KEY ("sport_league_id", "sport_league_phase_slot_id") REFERENCES "sport_league_phase_slots"("sport_league_id", "id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "sport_league_phase_slot_provider_mappings" ADD CONSTRAINT "sport_league_phase_slot_provider_mappings_provider_mapping_fkey" FOREIGN KEY ("sport_league_id", "sport_league_provider_mapping_id") REFERENCES "sport_league_provider_mappings"("sport_league_id", "id") ON DELETE CASCADE ON UPDATE CASCADE;


-- What the schema cannot say.
ALTER TABLE "sport_league_phase_slots"
  ADD CONSTRAINT "sport_league_phase_slots_key_format" CHECK ("key" ~ '^[A-Z][A-Z0-9_]*$'),
  ADD CONSTRAINT "sport_league_phase_slots_week_number" CHECK (("slot_kind" = 'WEEK') = ("week_number" IS NOT NULL) AND ("week_number" IS NULL OR "week_number" >= 1)),
  ADD CONSTRAINT "sport_league_phase_slots_series_games" CHECK (
    ("series_format" = 'SINGLE_GAME' AND "series_games" = 1)
    OR ("series_format" = 'BEST_OF' AND "series_games" >= 3 AND "series_games" % 2 = 1)
    OR ("series_format" = 'AGGREGATE' AND "series_games" >= 2));
ALTER TABLE "sport_league_phase_slot_provider_mappings"
  ADD CONSTRAINT "sport_league_phase_slot_provider_mappings_value" CHECK (("match_type" = 'CALENDAR_WEEK') = ("provider_value" IS NULL));

-- A week number is used once in a phase, and so is every kind but WEEK and TOURNAMENT.
CREATE UNIQUE INDEX "sport_league_phase_slots_one_week" ON "sport_league_phase_slots" ("sport_league_phase_id", "week_number") WHERE "slot_kind" = 'WEEK';
CREATE UNIQUE INDEX "sport_league_phase_slots_one_of_kind" ON "sport_league_phase_slots" ("sport_league_phase_id", "slot_kind") WHERE "slot_kind" NOT IN ('WEEK', 'TOURNAMENT');

-- Seed. Phases and slots are found by league id, so a league this database does not have gets
-- none. Today's round names, series lengths, squares rounds and NFL reseeding carry over; weeks go
-- to the longest season; golf has one slot per recurring tournament. Provider mappings are set
-- for the leagues BALLDONTLIE maps: REG:<week> and POST:<the round's place in the postseason>
-- for the code the adapter reduces a game to (slice 8), the calendar week for daily leagues'
-- weeks, and a normalized name for PGA tournaments. The College Football Playoff's date windows
-- come with slice 13.
